            '| 3 | 2 (1) | `8` | — |',
            '| 4 | 3 (8) | `16` | — |',
            '| 5 | 4 (3) | **`19`** | — |',
            '',
            'Sum = **19**; suffix max = `[8, 8, 8, 8, 3]`. Both directions make exactly one pass.',
