            '##10## Ends the output line. [printf]({c:printf})',
            '##11## `sum(1..3)` = `pref[4] - pref[1]` = 9 - 3 = 6. [printf]({c:printf})',
            '##12## `sum(0..4)` = `pref[5] - pref[0]` = 14 - 0 = 14. [printf]({c:printf})',
            '##13## Exit code 0 signals success. [return]({c:return})',
