            '~~~',
            '',
            '## Why It Works (invariant)',
            '',
            'After the build loop, `pref[i]` equals `a[0] + ... + a[i-1]` — the invariant holds by induction, since each step adds exactly the next element. Because `a[l..r] = (a[0]+...+a[r]) - (a[0]+...+a[l-1]) = pref[r+1] - pref[l]`, the subtraction telescopes every element before `l` out of the total.',
            '',
            '## Complexity',
            '',
            '| Operation | Complexity | Why |',
            '|---|---|---|',
            '| Build (1D) | **O(n)** | One pass over the array |',
            '| Range query | **O(1)** | Single subtraction |',
            '| Space | **O(n)** | One extra array of size n+1 |',
            '| Build (2D) | O(mn) | One pass over the matrix |',
            '| Submatrix query | O(1) | Inclusion-exclusion on four corners |',
            '',
            '> [!success] The key insight',
            '> Repeated "sum this window" questions become one precomputation plus trivial lookups. Never re-scan a range you have already totalled.',
            '',
            '## Variants',
            '',
            '| Variant | Idea | Typical use |',
            '|---|---|---|',
            '| 1D prefix sum | `pref[i+1] = pref[i] + a[i]` | Range sums, subarray equality |',
            '| 2D prefix sum | Inclusion-exclusion on corners | Submatrix sums, image blur |',
            '| Prefix XOR / product | Same idea, different operator | XOR subarrays, zero-product checks |',
            '| HashMap + prefix | Store the earliest `pref` index | Subarray sum equals k |',
            '| Parallel scan | Hillis-Steele / Blelloch | GPU reductions |',
            '',
            '## Edge Cases',
            '',
            '1. **Empty range** (`l > r`) — the subtraction still runs; decide and document your convention.',
            '2. **Whole array** — `l = 0, r = n-1` gives `pref[n] - pref[0]`, the full total.',
            '3. **Overflow** — prefix values can reach n x max(a); use 64-bit integers for large inputs.',
            '4. **Negative numbers** — `pref` is no longer monotone, but the subtraction stays correct.',
            '',
            '## Common Mistakes',
            '',
            '- **Off-by-one in the query formula**: the 0-based inclusive form is `pref[r+1] - pref[l]`; mixing in `pref[r]` gives the wrong window.',
            '- **Forgetting `pref[0] = 0`** — without the sentinel, `l = 0` queries underflow.',
            '- **Mutating `a` after building `pref`** — the prefix cache goes stale.',
            '- **Rebuilding `pref` inside a loop** — that defeats the O(1) query; build it once.',
            '',
            '## Applications',
            '',
            '- **Subarray sum equals k** — pair `pref` with a hashmap of first occurrences.',
            '- **Range sums / range averages** (LeetCode 303, 304).',
            '- **2D image blur & matrix queries** — box sums in O(1) per window.',
            '- **Count of subarrays divisible by k** — bucket the `pref` remainders.',
            '- **Balanced parentheses / stock differences** — the prefix of a +1/-1 array locates imbalances.',
            '',
