            '| `+5` to `[0..1]` | `diff[0] += 5`, `diff[2] -= 5` | `[5, 3, -3, 0, -2, -3, 0]` |',
            '',
            'Now run the prefix: `arr[0]=5`, `arr[1]=5+3=8`, `arr[2]=8-3=5`, `arr[3]=5+0=5`, `arr[4]=5-2=3`, `arr[5]=3-3=0`. Final: **`[5, 8, 5, 5, 3, 0]`**.',
            '',
