            '',
            '> **Definition.** Sorting rearranges an array so its elements are in a defined order. It is the most reused primitive in interviews: it enables binary search, two pointers, greedy ordering, and kth-element queries.',
            '',
            '## History & Origin',
            '',
            'Sorting predates computers: the US census was sorted with punched-card machines in the 1890s (Hollerith). As computer algorithms: **merge sort** (John von Neumann, 1945), **quicksort** (Tony Hoare, 1959, published in CACM 1962), and **heapsort** (Williams and Floyd, 1964) form the classic trio. [Wikipedia: Sorting algorithm](https://en.wikipedia.org/wiki/Sorting_algorithm), [Wikipedia: Quicksort](https://en.wikipedia.org/wiki/Quicksort), [Wikipedia: Merge sort](https://en.wikipedia.org/wiki/Merge_sort)',
