            '',
            '## Why It Works (invariant)',
            '',
            'After the first loop, `freq[v]` equals the number of times `v` appears in the input — each occurrence adds exactly one, and every occurrence is visited once. `best`/`bestCount` maintain the champion by the rule "whoever holds the strictly largest count after every step", so at the end `best` is a most-frequent element. The second loop prints each value exactly once (the `printed` set guards repeats) in the order it first appeared.',
            '',
            '## Complexity',
            '',
            '| Aspect | Value | Why |',
            '|---|---|---|',
            '| Time | **O(n)** average | Each element enters and leaves once |',
            '| Space | **O(k)** | One entry per distinct value (or O(max value) for a frequency array) |',
            '| Lookup | O(1) amortized | Hash map operations are constant on average |',
            '',
