            '> When keys are small bounded integers (letters, 0..10^6), a plain array indexed by value beats a hash map: no hashing cost, guaranteed O(1), tiny memory. Reach for a map only for large or arbitrary keys.',
            '',
            '## The Two-Sum Pattern',
            '',
            'While scanning, check whether the **complement** (`target - x`) was already seen. This collapses a nested loop to one pass.',
            '',
            '`for x in a: if target - x in seen: return ...; seen[x] = index`',
            '',
            '## Applications',
            '',
            '| Problem | Hash key |',
            '|---|---|',
            '| Two Sum / 3Sum | complement |',
            '| First non-repeating char | char count |',
            '| Majority element | element count |',
            '| Group anagrams | sorted string / char tuple |',
            '| Subarray sum = k | prefix sum seen before |',
            '| Longest subarray | prefix + index map |',
            '',
