            '# Matrix / 2D Array',
            '',
            '> **Definition.** A matrix is an array of rows: `a[i][j]` is the cell in row `i`, column `j`. The core skills are safe indexing, the four traversal directions, and the standard transform recipes — transpose, rotate, spiral.',
            '',
            '## History & Origin',
            '',
            'Matrices predate computers: the ancient Chinese text *Nine Chapters on the Mathematical Art* (~3rd century BCE) solves systems of linear equations by manipulating rods on a board, which is Gaussian elimination in disguise. The name **matrix** was coined by **James Joseph Sylvester** in 1850, and matrix multiplication was developed by **Arthur Cayley** in the 1850s. [Wikipedia: Matrix (mathematics)](https://en.wikipedia.org/wiki/Matrix_%28mathematics%29)',
            '',
            'In interviews, 2D arrays are a favourite because indexing bugs are easy and transforms have neat recipes. The 90-degree rotation via "transpose + reverse rows" is LeetCode 48. [LeetCode 48: Rotate Image](https://leetcode.com/problems/rotate-image/)',
            '',
            '## Intuition',
            '',
            'A 2D array is just a list of lists. **Transposing** turns rows into columns by swapping `a[i][j]` with `a[j][i]` across the main diagonal. Reversing every row after a transpose turns the matrix 90° clockwise — each column becomes a row, and the reversal re-orders it correctly.',
            '',
