            '    for (int i = 0; i < 4; i++) {',
            '        if (k == 0 || a[i][0] > res[k - 1][1]) {',
            '            res[k][0] = a[i][0];',
            '            res[k][1] = a[i][1];',
            '            k++;',
            '        } else if (a[i][1] > res[k - 1][1]) {',
            '            res[k - 1][1] = a[i][1];',
