            '',
            '> **Definition.** The Dutch National Flag (DNF) problem: given an array whose values come from three groups (traditionally the three colours of the Dutch flag: red, white, blue), rearrange them in a **single pass with constant extra space** so all equal values are grouped and the three groups are in order.',
