            '    return 0;',
            '}',
            '---',
            '##1## [vector](https://en.cppreference.com/w/cpp/container/vector) stores the input array dynamically.',
            '##2## sfx is initialized with n+1 elements all set to 0 as the right [sentinel](https://en.wikipedia.org/wiki/Sentinel_value).',
            '##3## Loop builds suffix sums from right to left, each element [accumulating](https://en.cppreference.com/w/cpp/numeric/accumulate) the rest.',
