            '~~~',
            '',
            '~~~explain',
            'lang: java',
            'group: circulararray',
            'import java.util.*;',
            'public class Main {',
            '    public static void main(String[] args) {',
            '        int SIZE = 4;',
            '        int[] buf = new int[SIZE];',
            '        for (int v = 1; v <= 7; v++) {',
            '            int idx = v % SIZE;',
            '            buf[idx] = v;',
            '            System.out.print("Push " + v + " -> buf[" + idx + "], state:");',
            '            for (int i = 0; i < SIZE; i++)',
