            '##3## A [stack](https://en.cppreference.com/w/cpp/container/stack) stores indices in decreasing [order](https://en.wikipedia.org/wiki/Monotonic_function).',
            '##4## [stk.top()](https://en.cppreference.com/w/cpp/container/stack/top) accesses the top index [efficiently](https://en.cppreference.com/w/cpp/container/stack).',
            '##5## The [while loop](https://en.cppreference.com/w/cpp/language/while) pops elements smaller than the current value.',
