            '        int n = a.length;',
            '        int[] nge = new int[n];',
            '        Arrays.fill(nge, -1);',
            '        Deque<Integer> stk = new ArrayDeque<>();',
            '        for (int i = 0; i < n; i++) {',
            '            while (!stk.isEmpty() && a[stk.peek()] < a[i]) {',
            '                nge[stk.pop()] = a[i];',
            '            }',
            '            stk.push(i);',
            '        }',
            '        StringBuilder sb = new StringBuilder();',
            '        for (int i = 0; i < n; i++) {',
