            '}',
            '---',
            '##1## Takes a [vector]({cpp:vector}) of next pointers by reference for efficiency.',
            '##2## Initialize both pointers at head using [auto]({cpp:auto}) style.',
            '##3## Phase one: advance until pointers meet [namespace]({cpp:namespace}).',
            '##4## Slow advances one step per iteration using [pair]({cpp:pair}).',
            '##5## Fast advances two steps using nested array indexing [max]({cpp:max}).',
            '##6## Break out of loop when cycle is confirmed [min]({cpp:min}).',
            '##7## Phase two: reset slow to head [vector]({cpp:vector}).',
            '##8## Both move one step at a time until meeting at cycle entrance [accumulate]({cpp:accumulate}).',
            '##9## Return the cycle start node [cout]({cpp:cout}).',
