            '~~~',
            '',
            '~~~explain',
            'lang: java',
            'group: fastslowptr',
            'import java.util.*;',
            'class Main {',
            '    static int detectCycle(int[] next, int head) {',
            '        int slow = head, fast = head;',
            '        do {',
            '            slow = next[slow - 1];',
            '            fast = next[next[fast - 1] - 1];',
            '        } while (slow != fast);',
            '        slow = head;',
            '        while (slow != fast) {',
            '            slow = next[slow - 1];',
            '            fast = next[fast - 1];',
            '        }',
            '        return slow;',
            '    }',
