            '        int start = detectCycle(next, head);',
            '        System.out.println("Cycle detected, start = " + start);',
            '    }',
            '}',
            '---',
            '##1## Import [Arrays]({java:import}) for utility support.',
            '##2## Phase one uses a do-while loop to guarantee at least one advance [for]({java:for}).',
            '##3## Slow moves one node using [class]({java:class}) static method.',
            '##4## Fast moves two nodes with nested array indexing [if]({java:if}).',
            '##5## Loop continues until slow and fast meet [return]({java:return}).',
            '##6## Reset slow to head for phase two [HashMap]({java:for}).',
            '##7## Both advance one step until meeting at cycle start [while]({java:for}).',
            '##8## Return the cycle entrance value [main]({java:main}).',
            '##9## Main sets up next array and prints the result [System.out.println]({java:main}).',
            '~~~',
            '',
            '~~~explain',
            'lang: python',
            'group: fastslowptr',
            'def detect_cycle(next_list, head):',
            '    slow = fast = head',
